-- Extração assistida de documentos para Controles, Infraestrutura e Treinamentos.
USE `gmodelo_dbp`;
SET NAMES utf8mb4;

ALTER TABLE `documentos` ADD COLUMN `DADOS_DOCUMENTO_IA` JSON NULL COMMENT 'Última extração assistida do documento';
ALTER TABLE `ml_infraestrutura` ADD COLUMN `DADOS_DOCUMENTO_IA` JSON NULL COMMENT 'Última extração assistida da infraestrutura';
ALTER TABLE `ml_treinamentos` ADD COLUMN `DADOS_DOCUMENTO_IA` JSON NULL COMMENT 'Última extração assistida do treinamento';

INSERT INTO `ia_prompts` (`codigo`,`nome_pt`,`nome_en`,`nome_es`,`prompt_pt`,`prompt_en`,`prompt_es`) VALUES
('CONTROLE_DOCUMENTO','Preenchimento de controle por documento','Control completion from document','Completar control desde documento','Leia o documento do controle e extraia somente informações claramente identificadas. Retorne exclusivamente JSON válido no formato {"codigo":null,"titulo":null,"descricao":null,"observacao":null,"confianca":0,"alertas":[]}. Não invente informações. Use null quando não estiver claramente disponível.','Read the control document and extract only clearly identified information. Return exclusively valid JSON in the format {"codigo":null,"titulo":null,"descricao":null,"observacao":null,"confianca":0,"alertas":[]}. Do not invent information.','Lea el documento del control y extraiga únicamente información claramente identificada. Devuelva exclusivamente JSON válido con el formato {"codigo":null,"titulo":null,"descricao":null,"observacao":null,"confianca":0,"alertas":[]}. No invente información.'),
('INFRAESTRUTURA_DOCUMENTO','Preenchimento de infraestrutura por documento','Infrastructure completion from document','Completar infraestructura desde documento','Leia o documento da infraestrutura e extraia somente informações claramente identificadas. Retorne exclusivamente JSON válido no formato {"descricao":null,"atributos":null,"observacao":null,"confianca":0,"alertas":[]}. Não invente informações. Use null quando não estiver claramente disponível.','Read the infrastructure document and extract only clearly identified information. Return exclusively valid JSON in the format {"descricao":null,"atributos":null,"observacao":null,"confianca":0,"alertas":[]}. Do not invent information.','Lea el documento de infraestructura y extraiga únicamente información claramente identificada. Devuelva exclusivamente JSON válido con el formato {"descricao":null,"atributos":null,"observacao":null,"confianca":0,"alertas":[]}. No invente información.'),
('TREINAMENTO_DOCUMENTO','Preenchimento de treinamento por documento','Training completion from document','Completar capacitación desde documento','Leia o documento do treinamento e extraia somente informações claramente identificadas. Retorne exclusivamente JSON válido no formato {"descricao":null,"observacao":null,"confianca":0,"alertas":[]}. Não invente informações. Use null quando não estiver claramente disponível.','Read the training document and extract only clearly identified information. Return exclusively valid JSON in the format {"descricao":null,"observacao":null,"confianca":0,"alertas":[]}. Do not invent information.','Lea el documento de capacitación y extraiga únicamente información claramente identificada. Devuelva exclusivamente JSON válido con el formato {"descricao":null,"observacao":null,"confianca":0,"alertas":[]}. No invente información.')
ON DUPLICATE KEY UPDATE `prompt_pt`=VALUES(`prompt_pt`),`prompt_en`=VALUES(`prompt_en`),`prompt_es`=VALUES(`prompt_es`),`alterado_em`=NOW();

INSERT INTO `registros_migracao` (`codigo_migracao`,`origem`,`destino`,`tipo`,`versao`,`status`,`quantidade_registros`,`iniciada_em`,`concluida_em`,`detalhes`) VALUES
('IA_EXTRACAO_DOCUMENTOS_174','gmodelo_dbp.documentos; gmodelo_dbp.ml_infraestrutura; gmodelo_dbp.ml_treinamentos; gmodelo_dbp.ia_prompts','campos JSON e prompts específicos para documentos','ESTRUTURA','1.0.0','CONCLUIDA',3,NOW(),NOW(),JSON_OBJECT('tipos',JSON_ARRAY('controles','infraestrutura','treinamentos'),'confirmacao_usuario',true))
ON DUPLICATE KEY UPDATE `status`=VALUES(`status`),`concluida_em`=VALUES(`concluida_em`),`detalhes`=VALUES(`detalhes`);
